from collections import Counter, deque
def transform(grid):
    H,W=len(grid),len(grid[0])
    bg=Counter(c for r in grid for c in r).most_common(1)[0][0]
    out=[[bg]*W for _ in range(H)]
    seen=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if grid[i][j]!=bg and not seen[i][j]:
                col=grid[i][j]; comp=[]; q=deque([(i,j)]); seen[i][j]=True
                while q:
                    y,x=q.popleft(); comp.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and grid[ny][nx]==col:
                            seen[ny][nx]=True; q.append((ny,nx))
                if len(comp)>=6:
                    ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
                    for y in range(min(ys),max(ys)+1):
                        for x in range(min(xs),max(xs)+1):
                            out[y][x]=col
    return out
